namespace EntMap.Constants;

public static class MapperSourceGeneratorConstants
{
    public static string EntMapGlobalRegisterClassName => "EntMapperMaps";
        
    public static string GetEntMapGlobalRegisterSource(string namespaceName) => $$"""
          // EntMapGenerate <auto-generated />
          #nullable enable
          using System;
          using System.Linq;

          namespace {{namespaceName}}
          {
              internal static partial class {{GlobalMapperConstants.ClassName}}
              {
                  private static readonly System.Collections.Generic.Dictionary<(System.Type, System.Type), System.Delegate> _mappers = new();

                  static {{GlobalMapperConstants.ClassName}}()
                  {
                      InitMappers();
                  }

                  static partial void InitMappers();

                  public static TTarget Map<TTarget>(object source)
                  {
                      if (source == null) return default!;
              
                      var sourceType = source.GetType();
                      var targetType = typeof(TTarget);
                      var key = (sourceType, targetType);
              
                      if (_mappers.TryGetValue(key, out var del))
                      {
                          return ((System.Func<object, TTarget>)del)(source);
                      }

                      if (source is System.Collections.IEnumerable enumerable && targetType.IsGenericType)
                      {
                          var targetItemType = targetType.GetGenericArguments().FirstOrDefault();
                          if (targetItemType != null)
                          {
                              var listType = typeof(System.Collections.Generic.List<>).MakeGenericType(targetItemType);
                              var list = (System.Collections.IList)System.Activator.CreateInstance(listType)!;
                              foreach (var item in enumerable)
                              {
                                  if (item == null) continue;
                                  var mapMethod = typeof({{GlobalMapperConstants.ClassName}}).GetMethod("Map")!.MakeGenericMethod(targetItemType);
                                  list.Add(mapMethod.Invoke(null, new[] { item }));
                              }
                              return (TTarget)list;
                          }
                      }

                      throw new System.InvalidOperationException($"Mapping from {sourceType.Name} to {targetType.Name} is not generated.");
                  }
              }
          }
          """;
        
    public static string EntMapInlineGlobalRegisterClassName => "EntMapperInline";
        
    public static string GetEntMapInlineGlobalRegisterSource(string namespaceName) => $$"""
          // EntMapGenerate <auto-generated />
          namespace {{namespaceName}}
          {
              internal static partial class {{GlobalMapperConstants.ClassName}}
              {
                  /// <summary> Расширенный метод маппинга игнорируя профиль, для этого нужно подключить функцию intercerptors в csproj <br/>
                  ///"<InterceptorsNamespaces>$(InterceptorsNamespaces);EntMap.Example;EntMap.Generators</InterceptorsNamespaces>
                  /// </summary>
                  public static TTarget Map<TSource, TTarget>(TSource source, System.Action<InlineConfig<TSource, TTarget>> config)
                      => throw new System.InvalidOperationException("Этот метод должен был быть перехвачен компилятором.");

                  public class InlineConfig<TSource, TTarget>
                  {
                      public InlineConfig<TSource, TTarget> ForMember<TValue>(
                          System.Linq.Expressions.Expression<System.Func<TTarget, TValue>> memberOptions, 
                          System.Func<TSource, TValue> mappingFunction) => this;
                  }
              }
          }
          
          // Фикс CS0234 для .NET 10: Объявляем внутренний атрибут, доступный во всех файлах генерируемого кода
          namespace System.Runtime.CompilerServices
          {
              [System.AttributeUsage(System.AttributeTargets.Method, AllowMultiple = true)]
              internal sealed class InterceptsLocationAttribute : System.Attribute
              {
                  // Конструктор для старых версий (на всякий случай, чтобы не падал анализатор)
                  public InterceptsLocationAttribute(string filePath, int line, int character) { }
          
                  // Конструктор для стабильной версии .NET 10 (используется InterceptableLocation)
                  public InterceptsLocationAttribute(int version, string data) { }
              }
          }
          
          """;
}